```ts
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): ((msg: SSEMessage<string>) => Effect.Effect<A, ParseResult.ParseError, R>) => {
  const members = getUnionMembersWithTags(schema.ast)
  if (members === undefined) {
    const decode = makeEventDecoder(schema)
    return (msg) => decode(msg.data)
  }
  const decodeMember = new Map(members.map(m => [m.tag, Schema.decodeUnknown(Schema.make(m.ast))]))
  const fallback = Schema.decodeUnknown(schema)
  return (msg) => {
    if (msg.event !== undefined && decodeMember.has(msg.event)) {
      return Effect.flatMap(parseJson(msg.data), decodeMember.get(msg.event)!)
    }
    return Effect.flatMap(parseJson(msg.data), fallback)
