 *
 * @example
 * ```ts
 * import { HttpApiSSE } from "@effect/platform"
 *
 * HttpApiSSE.formatMessage({ data: "hello\nworld", event: "greeting" })
 * // "data: hello\ndata: world\nevent: greeting\n\n"
 * ```
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatMessage = <A>(msg: SSEMessage<A>): string => {
  let out = ""
  if (msg.data !== undefined) {
    for (const line of String(msg.data).split("\n")) {
      out += `data: ${line}\n`
    }
  }
  if (msg.event !== undefined) {
    out += `event: ${msg.event}\n`
  }
  if (msg.id !== undefined) {
    out += `id: ${msg.id}\n`
  }
  if (msg.retry !== undefined) {
    out += `retry: ${msg.retry}\n`
  }
