const parseSSEMessage = (text: string): SSEMessage.Any => {
  const msg: SSEMessage.Any = { data: "" }
  let hasData = false
  for (const line of text.split("\n")) {
    if (line.length === 0 || line.startsWith(":")) {
      continue
    }
    const index = line.indexOf(":")
    const field = index === -1 ? line : line.slice(0, index)
    let value = index === -1 ? "" : line.slice(index + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        msg.data = hasData ? `${msg.data}\n${value}` : value
        hasData = true
        break
