const unwrapAST = (ast: AST.AST): AST.AST => {
  let node = ast
  while (true) {
    if (node._tag === "Suspend") {
      node = node.f()
    } else if (node._tag === "Transformation") {
      node = node.to
    } else if (node._tag === "Refinement") {
      node = node.from
    } else {
      return node
    }
  }
}

const getUnionMemberTags = (ast: AST.AST): Map<string, AST.AST> | undefined => {
  const resolved = unwrapAST(ast)
  if (resolved._tag !== "Union") {
    return undefined
  }
  const members = new Map<string, AST.AST>()
  for (const member of resolved.types) {
    const tag = extractMemberTag(member)
    if (tag !== undefined) {
      members.set(tag, member)
    }
  }
  return members
}

const extractMemberTag = (member: AST.AST): string | undefined => {
  const resolved = unwrapAST(member)
  const typeLiteral = resolved._tag === "Declaration" ?
    resolved.typeParameters.find((t): t is AST.TypeLiteral => t._tag === "TypeLiteral") :
    resolved._tag === "TypeLiteral" ? resolved : undefined
  if (typeLiteral !== undefined) {
    const ps = typeLiteral.propertySignatures.find((p) => p.name === "_tag" && !p.isOptional)
    if (ps !== undefined) {
      const type = unwrapAST(ps.type)
      if (type._tag === "Literal" && typeof type.literal === "string") {
        return type.literal
      }
    }
  }
  const identifier = AST.getIdentifierAnnotation(resolved)
  return Option.isSome(identifier) ? identifier.value : undefined
}
