/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import * as Option from "effect/Option"
import * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import * as HttpClientError from "./HttpClientError.js"
import * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * The `Content-Type` used for `Server-Sent Events` responses.
 *
 * @since 1.0.0
 * @category constants
 */
export const contentType: "text/event-stream" = "text/event-stream"

/**
 * Represents a single `Server-Sent Event` message, as defined by the
 * [`Server-Sent Events` event stream format](https://html.spec.whatwg.org/multipage/server-sent-events.html).
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage<A = unknown> {
  /**
   * The data payload of the event.
   *
   * Multi-line data payloads are emitted as multiple `data:` fields on the
   * wire.
   */
  readonly data: A
  /**
   * Optional event name, emitted as the `event:` field.
   */
  readonly event?: string | undefined
  /**
   * Optional event id, emitted as the `id:` field.
   */
  readonly id?: string | undefined
  /**
   * Optional reconnection time (in milliseconds), emitted as the `retry:` field.
   */
  readonly retry?: number | undefined
}

/**
 * @since 1.0.0
 * @category models
 */
export declare namespace SSEMessage {
  /**
   * An `SSEMessage` with a string `data` payload, as produced when parsing
   * the wire format.
   *
   * @since 1.0.0
   * @category models
   */
  export interface Any extends SSEMessage<string> {}
}

/**
 * Format an `SSEMessage` into its wire representation, terminated by a blank
 * line.
 *
 * Multi-line data payloads are split and emitted as multiple `data:` fields.
 *
 * @example
 * ```ts
 * import { HttpApiSSE } from "@effect/platform"
 *
 * HttpApiSSE.formatMessage({ data: "hello\nworld", event: "greeting" })
 * // "data: hello\ndata: world\nevent: greeting\n\n"
 * ```
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatMessage = <A>(msg: SSEMessage<A>): string => {
  let out = ""
  if (msg.data !== undefined) {
    for (const line of String(msg.data).split("\n")) {
      out += `data: ${line}\n`
    }
  }
  if (msg.event !== undefined) {
    out += `event: ${msg.event}\n`
  }
  if (msg.id !== undefined) {
    out += `id: ${msg.id}\n`
  }
  if (msg.retry !== undefined) {
    out += `retry: ${msg.retry}\n`
  }
  return out + "\n"
}

/**
 * Format a data-only `SSEMessage` from an arbitrary value. The value is
 * JSON-encoded before being formatted.
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatDataMessage = <A>(data: A): string =>
  formatMessage({ data: JSON.stringify(data) })

/**
 * Create an encoder for a `Server-Sent Events` message from a `Schema`.
 *
 * The returned function encodes a value with the schema and formats the
 * encoded value as a data-only `SSE` message.
 *
 * @since 1.0.0
 * @category codecs
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): ((a: A) => Effect.Effect<string, ParseResult.ParseError, R>) => {
  const encode = Schema.encodeUnknown(schema)
  return (a) => Effect.map(encode(a), formatDataMessage)
}

/**
 * Create an encoder for `Server-Sent Events` messages from a `Schema`.
 *
 * Behaves like `makeEventEncoder`, except that when the schema is a tagged
 * union, the `event:` field of the message is set to the `_tag` of the
 * encoded value. Non-union schemas fall back to a data-only message.
 *
 * @since 1.0.0
 * @category codecs
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): ((a: A) => Effect.Effect<string, ParseResult.ParseError, R>) => {
  const isUnion = unwrapAST(schema.ast)._tag === "Union"
  const encode = Schema.encodeUnknown(schema)
  return (a) =>
    Effect.map(encode(a), (i) => {
      if (!isUnion) {
        return formatDataMessage(i)
      }
      const tag = typeof i === "object" && i !== null ? (i as Record<string, unknown>)._tag : undefined
      return typeof tag === "string" ?
        formatMessage({ data: JSON.stringify(i), event: tag }) :
        formatDataMessage(i)
    })
}

/**
 * Create a decoder for `Server-Sent Events` messages into a value described
 * by a `Schema`.
 *
 * The returned function parses a JSON string and decodes it with the schema.
 *
 * @since 1.0.0
 * @category codecs
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): ((data: string) => Effect.Effect<A, ParseResult.ParseError, R>) => {
  const decode = Schema.decodeUnknown(schema)
  return (data) =>
    Effect.flatMap(parseJson(data, schema.ast), (value) => decode(value))
}

/**
 * Create a decoder for `Server-Sent Events` messages into a value described
 * by a `Schema`.
 *
 * Behaves like `makeEventDecoder`, except that when the schema is a tagged
 * union, the `event` field of the message is used to select the union member
 * to decode. Non-union schemas fall back to decoding the message data with
 * the full schema.
 *
 * @since 1.0.0
 * @category codecs
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): ((msg: SSEMessage.Any) => Effect.Effect<A, ParseResult.ParseError, R>) => {
  const members = getUnionMemberTags(schema.ast)
  if (members === undefined) {
    const decode = makeEventDecoder(schema)
    return (msg) => decode(msg.data)
  }
  const decoders = new Map<string, (input: unknown) => Effect.Effect<A, ParseResult.ParseError, R>>()
  members.forEach((ast, tag) => {
    decoders.set(tag, Schema.decodeUnknown(Schema.make(ast)) as any)
  })
  const decodeAny = Schema.decodeUnknown(schema)
  return (msg) => {
    const decode = msg.event !== undefined ? decoders.get(msg.event) : undefined
    return Effect.flatMap(parseJson(msg.data, schema.ast), decode !== undefined ? decode : decodeAny)
  }
}

/**
 * Transform a stream of values into a stream of `Server-Sent Events` wire
 * format messages (encoded as `Uint8Array`).
 *
 * @since 1.0.0
 * @category constructors
 */
export const fromStream = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: (a: A) => Effect.Effect<string, E2, R2>
): Stream.Stream<Uint8Array, E | E2, R | R2> => {
  const textEncoder = new TextEncoder()
  return Stream.mapEffect(stream, (a) =>
    Effect.map(encoder(a), (message) => textEncoder.encode(message)))
}

/**
 * Transform a stream of values into a `Server-Sent Events`
 * `HttpServerResponse`.
 *
 * The response will use the `text/event-stream` content type, along with
 * `no-cache` and `keep-alive` headers.
 *
 * The current `Effect` context is captured and provided to the stream before
 * the response is built, so services remain available while the stream is
 * being run by the server.
 *
 * @since 1.0.0
 * @category constructors
 */
export const toResponse = <A, E, R, E2>(
  stream: Stream.Stream<A, E, R>,
  encoder: (a: A) => Effect.Effect<string, E2, R>
): Effect.Effect<HttpServerResponse.HttpServerResponse, E | E2, R> =>
  Effect.map(Effect.context<R>(), (context) =>
    HttpServerResponse.stream(
      Stream.provideContext(fromStream(stream, encoder), context),
      {
        contentType,
        headers: {
          "cache-control": "no-cache",
          connection: "keep-alive"
        }
      }
    ))

/**
 * Transform a `Server-Sent Events` response into a stream of decoded values.
 *
 * Partial chunks are buffered until a complete message (terminated by a
 * blank line) has been received.
 *
 * @since 1.0.0
 * @category constructors
 */
export const toStream = <A, E2, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (msg: SSEMessage.Any) => Effect.Effect<A, E2, R>
): Stream.Stream<A, HttpClientError.ResponseError | E2, R> => {
  const textDecoder = new TextDecoder()
  let buffer = ""
  const messages = Stream.flatMap(HttpClientResponse.stream(Effect.succeed(response)), (chunk) => {
    buffer += textDecoder.decode(chunk, { stream: true })
    const parts = buffer.split("\n\n")
    buffer = parts.pop()!
    return Stream.fromIterable(parts.map(parseSSEMessage))
  })
  return Stream.mapEffect(messages, decoder)
}

// -------------------------------------------------------------------------------------
// internal
// -------------------------------------------------------------------------------------

const parseJson = (data: string, ast: AST.AST): Effect.Effect<unknown, ParseResult.ParseError> =>
  Effect.try({
    try: () => JSON.parse(data),
    catch: (e) => ParseResult.parseError(new ParseResult.Type(ast, data, `Could not parse JSON: ${String(e)}`))
  })

const parseSSEMessage = (text: string): SSEMessage.Any => {
  let data: string | undefined
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const line of text.split("\n")) {
    if (line.length === 0 || line.startsWith(":")) {
      continue
    }
    const index = line.indexOf(":")
    const field = index === -1 ? line : line.slice(0, index)
    let value = index === -1 ? "" : line.slice(index + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data = data === undefined ? value : `${data}\n${value}`
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const n = Number(value)
        if (!Number.isNaN(n)) {
          retry = n
        }
        break
      }
    }
  }
  return {
    data: data ?? "",
    event,
    id,
    retry
  }
}

const unwrapAST = (ast: AST.AST): AST.AST => {
  let node = ast
  while (true) {
    if (node._tag === "Suspend") {
      node = node.f()
    } else if (node._tag === "Transformation") {
      node = node.to
    } else if (node._tag === "Refinement") {
      node = node.from
    } else {
      return node
    }
  }
}

const getUnionMemberTags = (ast: AST.AST): Map<string, AST.AST> | undefined => {
  const resolved = unwrapAST(ast)
  if (resolved._tag !== "Union") {
    return undefined
  }
  const members = new Map<string, AST.AST>()
  for (const member of resolved.types) {
    const tag = extractMemberTag(member)
    if (tag !== undefined) {
      members.set(tag, member)
    }
  }
  return members
}

const extractMemberTag = (member: AST.AST): string | undefined => {
  const resolved = unwrapAST(member)
  const typeLiteral = resolved._tag === "Declaration" ?
    resolved.typeParameters.find((t): t is AST.TypeLiteral => t._tag === "TypeLiteral") :
    resolved._tag === "TypeLiteral" ? resolved : undefined
  if (typeLiteral !== undefined) {
    const ps = typeLiteral.propertySignatures.find((p) => p.name === "_tag" && !p.isOptional)
    if (ps !== undefined) {
      const type = unwrapAST(ps.type)
      if (type._tag === "Literal" && typeof type.literal === "string") {
        return type.literal
      }
    }
  }
  const identifier = AST.getIdentifierAnnotation(resolved)
  return Option.isSome(identifier) ? identifier.value : undefined
}

