class EventB extends Schema.TaggedClass<EventB>()("EventB", { s: Schema.String }) {}
const Events = Schema.Union(EventA, EventB)

const joinChunks = (chunks: Chunk.Chunk<Uint8Array>) => {
  const arrays = Chunk.toArray(chunks)
  const total = arrays.reduce((n, c) => n + c.length, 0)
  const out = new Uint8Array(total)
  let offset = 0
  for (const c of arrays) {
    out.set(c, offset)
    offset += c.length
  }
  return new TextDecoder().decode(out)
}

