import {
  HttpApi,
  HttpApiBuilder,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  HttpClient,
  HttpClientRequest,
  HttpClientResponse
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { Effect, Layer, Schema, Stream, Context, Chunk } from "effect"

class SSEEventA extends Schema.TaggedClass<SSEEventA>()("EventA", { n: Schema.Number }) {}
class SSEEventB extends Schema.TaggedClass<SSEEventB>()("EventB", { s: Schema.String }) {}
const SSEEvents = Schema.Union(SSEEventA, SSEEventB)

class SSEApi extends HttpApiGroup.make("sse")
  .add(
    HttpApiEndpoint.sse("events")`/events`
      .addSuccess(SSEEvents)
  )
  .add(
    HttpApiEndpoint.sse("count")`/count`
      .addSuccess(Schema.Number)
  )
  .prefix("/sse")
{}

class SSETestApi extends HttpApi.make("sse-test").add(SSEApi) {}

const SSEValue = Context.Tag("SSEValue")<string, string>()

const SSEHandlersLive = HttpApiBuilder.group(
  SSETestApi,
  "sse",
  (handlers) =>
    handlers
      .handleStream("events", () =>
        Stream.mapEffect(Stream.fromIterable([1, 2, 3]), (n) =>
          Effect.map(SSEValue, (v) => n === 3 ? new SSEEventB({ s: v }) : new SSEEventA({ n }))))
      .handle("count", () => Effect.succeed(Stream.fromIterable([0, 1, 2])))
).pipe(Layer.provide(Layer.succeed(SSEValue, "sse-value")))

const SSELive = HttpApiBuilder.serve().pipe(
  Layer.provide(HttpApiBuilder.api(SSETestApi)),
  Layer.provide(SSEHandlersLive),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

const dump = (path: string) =>
  Effect.gen(function*() {
    const http = yield* HttpClient.HttpClient
    const res = yield* http.execute(HttpClientRequest.make("GET")(path))
    console.log(`== ${path} status:`, res.status)
    const bodyStream = HttpClientResponse.stream(Effect.succeed(res))
    const arr = Chunk.toArray(yield* Stream.runCollect(bodyStream))
    console.log(arr.map((c) => JSON.stringify(new TextDecoder().decode(c))).join(" | "))
  })

const main = dump("/sse/events").pipe(Effect.flatMap(() => dump("/sse/count"))).pipe(Effect.provide(SSELive))

Effect.runPromise(main).then(
  () => { console.log("DONE"); process.exit(0) },
  (e) => { console.log("ERROR:", e); process.exit(1) }
)
setTimeout(() => { console.log("TIMEOUT"); process.exit(1) }, 20000)
